  Definition cW_pre (rg : bvmap 5 word) : Prop :=
    getr rg 10 = Z_to_bv 64 pd /\ getr rg 11 = cv /\ getr rg 12 = Z_to_bv 64 n /\ getr rg 8 = Z_to_bv 64 s
    /\ getr rg 2 = Z_to_bv 64 (s - 2144).
  Definition cW_post (rg : bvmap 5 word) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S90|21;!1,20!1,2|600;!1+12!1,4|32;!1,4|33;!1,4|34;|10;!1,47$rg;R!2'_I13!2+A!3+<3!2'_K#1!3,314vv,6!2'714!2'=2/pd;!2+A!3+<3!2'_K#1!3,315vv,6!2'715/cv;!2+A!3+<3!2'_K#1!3,316vv,6!2'716!2'=2/n;!3+<3!2'_K#1!3,318vv,6!2'718!2'=2!2'H/s;!1,4|;060;").

  (* [comment removed for export] *)
  Lemma cWz_run : forall M regs,
    cW_pre regs -> n = 0%Z ->
    exists regs',
